/*!
 * \file sfa_tiling_nonquant.h
 * \brief
 */
#ifndef SFA_TILING_NONQUANT_H
#define SFA_TILING_NONQUANT_H

#include "register/tilingdata_base.h"
#include "exe_graph/runtime/tiling_context.h"
#include "fia_tiling_base.h"
#include "fia_tiling_info.h"
#include "ai_infra_sparse_flash_attention_gqa_split_core.h"
#include "ai_infra_sparse_flash_attention_gqa_tiling.h"
#include "ai_infra_sparse_flash_attention_gqa_tiling_v3.h"

namespace optiling {
namespace optilingSfa {
class SfaTilingNonQuant : public FiaTilingBase {
public:
    explicit SfaTilingNonQuant(gert::TilingContext *context) : FiaTilingBase(context) {}
    ~SfaTilingNonQuant() override = default;

protected:
    void InitTilingInfo(TilingInfo *tilingInfo) override;
    bool IsCapable() override;
    ge::graphStatus DoOpTiling() override;

private:
    ge::graphStatus GetPlatformInfo();
    void GenTilingKey();
    bool DealSameSeqEachBatch();

    void ZeroTensorProcess();
    void InitParams();

    void Split();
    void CreateSplitInput(SfaSplitCoreBaseInfo &baseInfo);
    void CreateSplitOutput(SfaOuterSplitParams &outerSplitParams, SfaFlashDecodeParams &fDParams, SfaSplitCoreRes &res);
    void CalcInnerSize(uint32_t seqSize);
    void CalcMBaseSize();

    bool IsFlashDecode(uint32_t coreNum);

    void CalcMmResSize();
    void CalcMaxMmResSize();

    uint32_t GetL2CacheOffFlag();

    void FillTilingBaseParams();
    void FillTilingPageAttenParams();
    void FillTilingMaskParams();
    void FillTilingWorkspaceParams();
    void FillTilingSparseFlashAttentionParams();
    void FillTiling();

    uint32_t CalcFlashDecodeParamNums(const uint32_t coreNum) const;
    uint64_t CalcNormalWorkspaceSize(uint32_t coreNum, int64_t mm1ResSize, int64_t mm2ResSize) const;
    uint64_t CalcFlashDecodeWorkspace(const uint32_t coreNum) const;
    void CalcWorkspaceSize();
    void CalcMaxWorkspaceSize();
    void CalcBlockDim(uint32_t coreNum);

    bool splitKVFlag_ = false;

    uint32_t coreNum_ = 0;
    IfaPerfMode perfMode_ = IfaPerfMode::NORMAL;
    uint32_t kvSplitPart_ = 1;
    int64_t mm1ResSize_ = 0;
    int64_t mm2ResSize_ = 0;
    uint32_t sInnerLoopTimes_ = 0;
    uint32_t sInnerSize_ = 0;
    uint32_t sInnerSizeTail_ = 0;
    uint32_t sInnerSizeAlign_ = 0;
    uint32_t kvSplit_ = 0;
    uint32_t usedCoreNum_ = 0;
    uint32_t l2CacheOffFlag_ = 0;

    // platform info
    uint32_t aicNum_ = 0;
    uint32_t aivNum_ = 0;
    size_t libapiSize_ = 0;

    // set info to context
    AiInfraSparseFlashAttentionGqaTilingData tilingData_;
    uint32_t blockDim_{0};
    uint64_t workspaceSize_{0};
    uint64_t tilingKey_{0};

    uint32_t headDimAlign_ = 0;
    uint32_t mBaseSize_ = 256;
    uint32_t mFdBaseSize_ = 8;
    bool softmaxWithBrcbFlag_ = false;

    // Tiling Info
    FiaTilingInfo *sfaInfo_ = nullptr;
};

} // namespace optilingSfa
} // namespace optiling
#endif // SFA_TILING_NONQUANT_H

