 * declaration here for testcase to use by extern the interface
 * @domain aclnn_ops_infer
 */

extern "C" aclnnStatus __attribute__((weak)) NnopbaseDisableOptionalInput(void *executor, const size_t irIndex);

aclnnStatus aclnnAiInfraSparseFlashAttentionGqaGetMaxWorkspaceSize(const aclTensor *query,
                                                                   const aclTensorList *key,
                                                                   const aclTensorList *value,
                                                                   const aclTensor *sparseIndices,
                                                                   double scaleValue,
                                                                   int64_t sparseBlockSize,
                                                                   const aclIntArray *actualSeqLengthsOptional,
                                                                   const aclIntArray *actualSeqLengthsKvOptional,
                                                                   const aclTensor *blockTableOptional,
                                                                   int64_t numHeads,
                                                                   int64_t numKeyValueHeads,
                                                                   char *inputLayout,
                                                                   char *inputLayoutKv,
                                                                   int64_t sparseMode,
                                                                   int64_t blockSize,
                                                                   bool softmaxLseFlag,
                                                                   const aclTensor *attentionOut,
                                                                   const aclTensor *softmaxLse,
                                                                   uint64_t *workspaceSize,
                                                                   aclOpExecutor **executor)
{
    const aclTensor *placeHolder = nullptr;
    const aclTensor *tempTensor = nullptr;
    const aclTensor *deqScale1Optional = nullptr;
    const aclTensor *pseShiftOptional = nullptr;
    const aclTensor *attenMaskOptional = nullptr;
    const aclTensor *quantScale1Optional = nullptr;
    const aclTensor *deqScale2Optional = nullptr;
    const aclTensor *quantScale2Optional = nullptr;
    const aclTensor *quantOffset2Optional = nullptr;
    const aclTensor *antiquantScaleOptional = nullptr;
    const aclTensor *antiquantOffsetOptional = nullptr;
    const aclTensor *queryPaddingSizeOptional = nullptr;
    const aclTensor *kvPaddingSizeOptional = nullptr;
    const aclTensor *keyAntiquantScaleOptional = nullptr;
    const aclTensor *keyAntiquantOffsetOptional = nullptr;
    const aclTensor *valueAntiquantScaleOptional = nullptr;
    const aclTensor *valueAntiquantOffsetOptional = nullptr;
    const aclTensor *keySharedPrefixOptional = nullptr;
    const aclTensor *valueSharedPrefixOptional = nullptr;
    const aclIntArray *actualSharedPrefixLenOptional = nullptr;
    const aclTensor *queryRopeOptional = nullptr;
    const aclTensor *keyRopeOptional = nullptr;
    const aclTensor *keyRopeAntiquantScaleOptional = nullptr;
    const aclTensor *dequantScaleQueryOptional = nullptr;
    const aclTensor *learnableSinkOptional = nullptr;
    const aclTensor *tensorKeySharedPrefixOptional = nullptr;
    const aclTensor *tensorValueSharedPrefixOptional = nullptr;
    int64_t preTokens = 65535;
    int64_t nextTokens = 65535;
    int64_t innerPrecise = 0;
    int64_t antiquantMode = 0;
    int64_t keyAntiquantMode = 0;
    int64_t valueAntiquantMode = 0;
    int64_t queryQuantMode = 0;

    OP_LOGD("start aclnnAiInfraSparseFlashAttentionGqaGetMaxWorkspaceSize");
    TensorPreProcessSfa(key, value);
    PrefixTensorPreProcessSfa(tensorKeySharedPrefixOptional, tensorValueSharedPrefixOptional);

    aclTensor *fakeActualSeqLengthsOptional{nullptr};
    aclTensor *fakeActualSeqLengthsKvOptional{nullptr};
    aclTensor *fakeActualSharedPrefixLenOptional{nullptr};

    // nullptr不处理， nullptr是空指针，这样不会影响原来就不传入actual seq length为空的逻辑
    aclnnStatus ret = FakeArraySfa(actualSeqLengthsOptional, fakeActualSeqLengthsOptional);
    CHECK_RET_CODE(ret, "Try alloc fake actualSeqLengthsOptional failed");
    ret = FakeArraySfa(actualSeqLengthsKvOptional, fakeActualSeqLengthsKvOptional);
    if (ret != ACLNN_SUCCESS) {
        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc fake actualSeqLengthsKvOptional failed");
        aclDestroyTensor(fakeActualSeqLengthsOptional); // 没有返回值无需校验
        return ret;
    }

    ret = FakeArraySfa(actualSharedPrefixLenOptional, fakeActualSharedPrefixLenOptional);
    if (ret != ACLNN_SUCCESS) {
        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc fake actualSharedPrefixLenOptional failed");
        aclDestroyTensor(fakeActualSeqLengthsOptional); // 没有返回值无需校验
        aclDestroyTensor(fakeActualSeqLengthsKvOptional);
        return ret;
    }

    AiInfraSparseFlashAttentionGqaProcessSoftmaxLse(softmaxLseFlag, softmaxLse, tempTensor, placeHolder);

    ret = aclnnInnerAiInfraSparseFlashAttentionGqaTensorGetWorkspaceSize(query,
                                                                         key,
                                                                         value,
                                                                         sparseIndices,
                                                                         pseShiftOptional,
                                                                         attenMaskOptional,
                                                                         fakeActualSeqLengthsOptional,
                                                                         fakeActualSeqLengthsKvOptional,
                                                                         deqScale1Optional,
                                                                         quantScale1Optional,
                                                                         deqScale2Optional,
                                                                         quantScale2Optional,
                                                                         quantOffset2Optional,
                                                                         antiquantScaleOptional,
                                                                         antiquantOffsetOptional,
                                                                         blockTableOptional,
                                                                         queryPaddingSizeOptional,
                                                                         kvPaddingSizeOptional,
                                                                         keyAntiquantScaleOptional,
                                                                         keyAntiquantOffsetOptional,
                                                                         valueAntiquantScaleOptional,
                                                                         valueAntiquantOffsetOptional,
                                                                         tensorKeySharedPrefixOptional,
                                                                         tensorValueSharedPrefixOptional,
                                                                         fakeActualSharedPrefixLenOptional,
                                                                         queryRopeOptional,
                                                                         keyRopeOptional,
                                                                         keyRopeAntiquantScaleOptional,
                                                                         dequantScaleQueryOptional,
                                                                         learnableSinkOptional,
                                                                         nullptr,
                                                                         nullptr,
                                                                         numHeads,
                                                                         sparseBlockSize,
                                                                         scaleValue,
                                                                         preTokens,
                                                                         nextTokens,
                                                                         inputLayout,
                                                                         inputLayoutKv,
                                                                         numKeyValueHeads,
                                                                         sparseMode,
                                                                         innerPrecise,
                                                                         blockSize,
                                                                         antiquantMode,
                                                                         softmaxLseFlag,
                                                                         keyAntiquantMode,
                                                                         valueAntiquantMode,
                                                                         queryQuantMode,
                                                                         0,
                                                                         0,
                                                                         attentionOut,
                                                                         placeHolder,
                                                                         workspaceSize,
                                                                         executor);
    if (softmaxLseFlag == false) {
        aclDestroyTensor(tempTensor);
    }
    aclDestroyTensor(fakeActualSeqLengthsOptional); // 只会成功，无需校验
    aclDestroyTensor(fakeActualSeqLengthsKvOptional);
    aclDestroyTensor(fakeActualSharedPrefixLenOptional);
    return ret;
}

aclnnStatus aclnnAiInfraSparseFlashAttentionGqaGetWorkspaceSize(const aclTensor *query,
                                                                const aclTensorList *key,
                                                                const aclTensorList *value,
                                                                const aclTensor *sparseIndices,
                                                                double scaleValue,
                                                                int64_t sparseBlockSize,
                                                                const aclIntArray *actualSeqLengthsOptional,
                                                                const aclIntArray *actualSeqLengthsKvOptional,
                                                                const aclTensor *blockTableOptional,
                                                                int64_t numHeads,
                                                                int64_t numKeyValueHeads,
                                                                char *inputLayout,
                                                                char *inputLayoutKv,
                                                                int64_t sparseMode,
                                                                int64_t blockSize,
                                                                bool softmaxLseFlag,
                                                                const aclTensor *attentionOut,
                                                                const aclTensor *softmaxLse,
                                                                uint64_t *workspaceSize,
                                                                aclOpExecutor **executor)
{
    const aclTensorList *tensorListKey = key;
    const aclTensorList *tensorListValue = value;
    TensorPreProcessSfa(tensorListKey, tensorListValue);

    const aclTensor *placeHolder = nullptr;
    const aclTensor *tempTensor = nullptr;
    const aclTensor *deqScale1Optional = nullptr;
    const aclTensor *pseShiftOptional = nullptr;
    const aclTensor *attenMaskOptional = nullptr;
    const aclTensor *quantScale1Optional = nullptr;
    const aclTensor *deqScale2Optional = nullptr;
    const aclTensor *quantScale2Optional = nullptr;
    const aclTensor *quantOffset2Optional = nullptr;
    const aclTensor *antiquantScaleOptional = nullptr;
    const aclTensor *antiquantOffsetOptional = nullptr;
    const aclTensor *queryPaddingSizeOptional = nullptr;
    const aclTensor *kvPaddingSizeOptional = nullptr;
    const aclTensor *keyAntiquantScaleOptional = nullptr;
    const aclTensor *keyAntiquantOffsetOptional = nullptr;
    const aclTensor *valueAntiquantScaleOptional = nullptr;
    const aclTensor *valueAntiquantOffsetOptional = nullptr;
    const aclTensor *keySharedPrefixOptional = nullptr;
    const aclTensor *valueSharedPrefixOptional = nullptr;
    const aclIntArray *actualSharedPrefixLenOptional = nullptr;
    const aclTensor *queryRopeOptional = nullptr;
    const aclTensor *keyRopeOptional = nullptr;
    const aclTensor *keyRopeAntiquantScaleOptional = nullptr;
    const aclTensor *dequantScaleQueryOptional = nullptr;
    const aclTensor *learnableSinkOptional = nullptr;
    const aclTensor *tensorKeySharedPrefixOptional = nullptr;
    const aclTensor *tensorValueSharedPrefixOptional = nullptr;
    int64_t preTokens = 65535;
    int64_t nextTokens = 65535;
    int64_t innerPrecise = 0;
    int64_t antiquantMode = 0;
    int64_t keyAntiquantMode = 0;
    int64_t valueAntiquantMode = 0;
    int64_t queryQuantMode = 0;

    AiInfraSparseFlashAttentionGqaProcessSoftmaxLse(softmaxLseFlag, softmaxLse, tempTensor, placeHolder);

    aclnnStatus ret = aclnnInnerAiInfraSparseFlashAttentionGqaGetWorkspaceSize(query,
                                                                               tensorListKey,
                                                                               tensorListValue,
                                                                               sparseIndices,
                                                                               pseShiftOptional,
                                                                               attenMaskOptional,
                                                                               actualSeqLengthsOptional,
                                                                               actualSeqLengthsKvOptional,
                                                                               deqScale1Optional,
                                                                               quantScale1Optional,
                                                                               deqScale2Optional,
                                                                               quantScale2Optional,
                                                                               quantOffset2Optional,
                                                                               antiquantScaleOptional,
                                                                               antiquantOffsetOptional,
                                                                               blockTableOptional,
                                                                               queryPaddingSizeOptional,
                                                                               kvPaddingSizeOptional,
                                                                               keyAntiquantScaleOptional,
                                                                               keyAntiquantOffsetOptional,
                                                                               valueAntiquantScaleOptional,
                                                                               valueAntiquantOffsetOptional,
                                                                               tensorKeySharedPrefixOptional,
                                                                               tensorValueSharedPrefixOptional,
                                                                               actualSharedPrefixLenOptional,
                                                                               queryRopeOptional,
                                                                               keyRopeOptional,
                                                                               keyRopeAntiquantScaleOptional,
                                                                               dequantScaleQueryOptional,
                                                                               learnableSinkOptional,
                                                                               nullptr,
                                                                               nullptr,
                                                                               numHeads,
                                                                               sparseBlockSize,
                                                                               scaleValue,
                                                                               preTokens,
                                                                               nextTokens,
                                                                               inputLayout,
                                                                               inputLayoutKv,
                                                                               numKeyValueHeads,
                                                                               sparseMode,
                                                                               innerPrecise,
                                                                               blockSize,
                                                                               antiquantMode,
                                                                               softmaxLseFlag,
                                                                               keyAntiquantMode,
                                                                               valueAntiquantMode,
                                                                               queryQuantMode,
                                                                               0,
                                                                               0,
                                                                               attentionOut,
                                                                               placeHolder,
                                                                               workspaceSize,
                                                                               executor);
    if (softmaxLseFlag == false) {
        aclDestroyTensor(tempTensor);
    }
    if (ret == 0) {
        if (NnopbaseDisableOptionalInput != nullptr) {
            NnopbaseDisableOptionalInput(*executor, 29U); // 29 is input irIndex，占位符
            NnopbaseDisableOptionalInput(*executor, 30U); // 30 is input irIndex，占位符
        }
    }
    return ret;
}

aclnnStatus aclnnAiInfraSparseFlashAttentionGqa(void *workspace,
                                                uint64_t workspaceSize,
                                                aclOpExecutor *executor,
                                                const aclrtStream stream)
{
    return aclnnInnerAiInfraSparseFlashAttentionGqa(workspace, workspaceSize, executor, stream);
}

