/*!
 * \file sparse_flash_attention_gqa_tiling_parse_sparse_block.cpp
 * \brief
 */
#include <iostream>
#include "error/ops_error.h"
#include "ai_infra_sparse_flash_attention_gqa_tiling_index.h"
#include "ai_infra_sparse_flash_attention_gqa_tiling_info_parser.h"

using namespace ge;
using namespace AscendC;
namespace optiling {
namespace optilingSfa {
ge::graphStatus SfaInfoParser::GetSparseBlockSizeAttrParaInfo()
{
    auto attrs = context_->GetAttrs();
    OPS_CHECK(attrs == nullptr, OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "attrs got from ge is nullptr"),
               return ge::GRAPH_FAILED);

    opParamInfo_.sparseBlockSize = attrs->GetAttrPointer<int64_t>(ATTR_SPARSE_BLOCK_SIZE_INDEX);

    return ge::GRAPH_SUCCESS;
}

void SfaInfoParser::GetSparseIndicesParaInfo()
{
    opParamInfo_.sparseIndices.desc = context_->GetInputDesc(SPARSE_INDICES_INDEX);
    opParamInfo_.sparseIndices.shape = context_->GetInputShape(SPARSE_INDICES_INDEX);
    return;
}

ge::graphStatus SfaInfoParser::GetSparseBlockSize()
{
    if (opParamInfo_.sparseBlockSize == nullptr) {
        OPS_LOG_E(opName_, "Attr %s not exist", SPARSE_BLOCK_SIZE_NAME.c_str());
        return ge::GRAPH_FAILED;
    }
    sparseBlockSize_ = *(opParamInfo_.sparseBlockSize);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SfaInfoParser::GetSparseBlockCount()
{
    auto sparseIndicesShape = FiaTilingShape(opParamInfo_.sparseIndices.shape->GetStorageShape(),
        qLayout_, SPARSE_BLOCK_INDICES_NAME, opName_, n2Size_);
    if (sparseIndicesShape.CheckHasD(__func__) != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }

    sparseBlockCount_ = static_cast<uint32_t>(sparseIndicesShape.GetD()); // 后面需要把qkHeadDim_改成uint64
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SfaInfoParser::ParseSparseFlashAttentionInfo(FiaTilingInfo &sfaInfo)
{
    if (GetSparseBlockSizeAttrParaInfo() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }

    GetSparseIndicesParaInfo();

    if (GetSparseBlockSize() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }

    if (GetSparseBlockCount() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }

    sfaInfo.sparseBlockSize = sparseBlockSize_;
    sfaInfo.sparseBlockCount = sparseBlockCount_;
    return ge::GRAPH_SUCCESS;
}
} // namespace optilingSfa
}

