        baseInfo.actualSeqS1Size = sfaInfo_->opParamInfo.actualSeqLengthsQ.tensor->GetData<int64_t>();
        baseInfo.isAccumSeqS1 = sfaInfo_->isAccumQSeq;
    }
    if (sfaInfo_->opParamInfo.actualSeqLengths.tensor != nullptr) {
