/**
 * @brief Calculates the actual start and end indices within the main array
 * for a given sparse block index, respecting array length and boundary index.
 * @param blockIndex The index of the sparse block.
 * @param sparseBlockSize The size of each sparse block.
 * @param arrayLength The total length of the array.
 * @param boundaryIndex The exclusive boundary index for valid data.
 * @return A pair<int64_t, int64_t> representing (start, end) indices, or (-1, -1) if invalid.
 */
__aicore__ inline Segment GetBlockStartEnd(int32_t blockIndex, int64_t sparseBlockSize, uint64_t arrayLength,
    uint64_t boundaryIndex) 
{
    int64_t start = blockIndex * sparseBlockSize;
    int64_t end = start + sparseBlockSize;

    end = sfa_sparse_block_service::Min(end, arrayLength);
    end = sfa_sparse_block_service::Min(end, boundaryIndex);
    if (start >= end) {
        return {-1, -1};
    }
    return {start, end};
}

