        GlobalTensor<int32_t> sparseBlockIndices, uint64_t boundaryIndex, uint64_t l1Size) :
        arrayLength_(arrayLength), sparseBlockSize_(sparseBlockSize),
        sparseBlockCount_(sparseBlockCount), sparseBlockIndices_(sparseBlockIndices),
        boundaryIndex_(boundaryIndex), l1Size_(l1Size)
    {
