179	bool CheckGqaDSupport(gert::TilingContext *context)
180	{
181	    int64_t queryD = 0;
182	    int64_t queryRopeD = 0;
183	    int64_t valueD = 0;
184	    if (GetQkvD(context, queryD, queryRopeD, valueD) != true) {
185	        return false;
186	    }
187	
188	    // D的组合(128+0,128)(64+0,64)(128+64,128)(192+0,128)
189	    if ((queryD  == 128 && queryRopeD  == 0 && valueD == 128) || // 128: gqa qkvD
190	        (queryD  == 64 && queryRopeD  == 0 && valueD == 64) || // 64: gqa qkvD
191	        (queryD  == 128 && queryRopeD  == 64 && valueD == 128) || // 128: gqa qkvD, 64: mla ropeD
192	        (queryD  == 192 && queryRopeD  == 0 && valueD == 128)) { // 192: gqa qkD, 128: gqa valueD
193	        return true;
194	    }
195	
196	    return false;
197	}
