216	bool IsEmptyTensor(gert::TilingContext *context)
217	{
218	    auto qShape = context->GetInputShape(QUERY_INDEX);
219	    if ((qShape != nullptr) && (qShape->GetStorageShape().GetShapeSize() == 0)) {
220	        return true;
221	    }
222	
223	    auto attenoutShape = context->GetInputShape(ATTENTION_OUT_INDEX);
224	    if ((attenoutShape != nullptr) && (attenoutShape->GetStorageShape().GetShapeSize() == 0)) {
225	        return true;
226	    }
227	
228	    bool softmaxLseFlag = context->GetAttrs()->GetAttrPointer<bool>(SOFTMAX_LSE_FLAG_INDEX);
229	    if (softmaxLseFlag) {
230	        auto softmaxLseShape = context->GetInputShape(SOFTMAX_LSE_INDEX);
231	        if ((softmaxLseShape != nullptr) && (softmaxLseShape->GetStorageShape().GetShapeSize() == 0)) {
232	            return true;
233	        }
234	    }
235	
236	    uint32_t keyBIdx = 0;
237	    while ((context->GetDynamicInputShape(KEY_INDEX, keyBIdx)) != nullptr) {
238	        const gert::StorageShape *keyShape =
239	            const_cast<gert::StorageShape *>(context->GetDynamicInputShape(KEY_INDEX, keyBIdx));
240	        if (keyShape->GetStorageShape().GetShapeSize() == 0) {
241	            return true;
242	        }
243	        keyBIdx++;
244	    }
245	
246	    uint32_t valueBIdx = 0;
247	    while ((context->GetDynamicInputShape(VALUE_INDEX, valueBIdx)) != nullptr) {
248	        const gert::StorageShape *valueShape =
249	            const_cast<gert::StorageShape *>(context->GetDynamicInputShape(VALUE_INDEX, valueBIdx));
250	        if (valueShape->GetStorageShape().GetShapeSize() == 0) {
251	            return true;
252	        }
253	        valueBIdx++;
254	    }
255	
256	    return false;
257	}
