266	    auto actualSharedPrefixLen = context->GetOptionalInputTensor(ACTUAL_SHARED_PREFIX_LEN_INDEX);
267	    auto quantScale2 = context->GetOptionalInputTensor(QUANT_SCALE2_INDEX);
268	    auto quantOffset2 = context->GetOptionalInputTensor(QUANT_OFFSET2_INDEX);
269	    if (pseShift != nullptr ||
270	        queryPaddingSize != nullptr ||
271	        kvPaddingSize != nullptr ||
272	        keySharedPrefix != nullptr ||
273	        valueSharedPrefix != nullptr ||
274	        actualSharedPrefixLen != nullptr ||
275	        quantScale2 != nullptr ||
276	        quantOffset2 != nullptr) {
277	        return false;
278	    }
279	
280	    return true;
