283	bool CheckGqaConstrain(gert::TilingContext *context)
284	{
285	    if (CheckGqaInputLayoutSupport(context) &&
286	        !IsEmptyTensor(context) &&
287	        CheckGqaDSupport(context) &&
288	        CheckGqaFeatureSupport(context)) {
289	            return true;
290	    }
291	    return false;
292	}
