294	bool RouteToSfa(gert::TilingContext *context)
295	{
296	    if ((context == nullptr) || context->GetAttrs() == nullptr ||
297	    (context->GetInputDesc(QUERY_INDEX) == nullptr) ||
298	    (context->GetInputDesc(KEY_INDEX) == nullptr)) {
299	        return false;
300	    }
301	    auto platformInfoPtr = context->GetPlatformInfo();
302	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
303	    if (ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND310P) {
304	        return false;
305	    }
306	
307	    ge::DataType qDataType = context->GetInputDesc(QUERY_INDEX)->GetDataType();
308	    ge::DataType kDataType = context->GetInputDesc(KEY_INDEX)->GetDataType();
309	    bool isRopeSplit = (context->GetOptionalInputTensor(QUERY_ROPE_INDEX) != nullptr &&
310	        context->GetOptionalInputTensor(KEY_ROPE_INDEX) != nullptr);
311	    if (isRopeSplit) {
312	        // MLA非量化
313	        if ((qDataType == ge::DT_FLOAT16 || qDataType == ge::DT_BF16) && (qDataType == kDataType)) {
314	            if (CheckGqaConstrain(context)) {
315	                OPS_LOG_I(context->GetNodeName(), "SFA RopeSplit GQA No quant.");
316	                return true;
317	            }
318	            return false;
319	        }
320	    } else {
321	        // GQA非量化
322	        if ((qDataType == ge::DT_FLOAT16 || qDataType == ge::DT_BF16) && (qDataType == kDataType)) {
323	            OPS_LOG_I(context->GetNodeName(), "SFA GQA No quant.");
324	            return CheckGqaConstrain(context);
325	        }
326	    }
327	    return false;
328	}
