#include "opdev/op_dfx.h"
#include "opdev/tensor_view_utils.h"
using namespace op;

namespace l0op {
OP_TYPE_REGISTER(AiInfraSparseFlashAttentionPioneer);
AiInfraSparseFlashAttentionPioneerOutputs AiInfraSparseFlashAttentionPioneer(
    const aclTensor *query,
    const aclTensor *key,
    const aclTensor *value,
    const aclTensor *sparseIndices,
    const aclTensor *blockTableOptional,
    const aclTensor *actualSeqLengthsQueryOptional,
    const aclTensor *actualSeqLengthsKvOptional,
    const aclTensor *queryRopeOptional,
    const aclTensor *keyRopeOptional,
    const aclTensor *keySinkOptional,
    const aclTensor *valueSinkOptional,
    const aclTensor *metaDataOptional,
    double scaleValue,
    int64_t sparseBlockSize,
    char *layoutQueryOptional,
    char *layoutKvOptional,
    int64_t sparseMode,
    int64_t preTokens,
    int64_t nextTokens,
    int64_t attentionMode,
    bool returnSoftmaxLse,
    bool batchInvariant,
    aclOpExecutor *executor)
{
    // L0接口时延统计以及入参打印

    L0_DFX(AiInfraSparseFlashAttentionPioneer, query, key, value,
            sparseIndices, blockTableOptional, actualSeqLengthsQueryOptional,
            actualSeqLengthsKvOptional, queryRopeOptional, keyRopeOptional,
            keySinkOptional, valueSinkOptional, metaDataOptional,scaleValue, 
            sparseBlockSize, layoutQueryOptional, layoutKvOptional, sparseMode, 
            preTokens, nextTokens, attentionMode, returnSoftmaxLse, batchInvariant);

    const aclTensor *attentionOut = executor->AllocTensor(query->GetDataType(), Format::FORMAT_ND, Format::FORMAT_ND);
    const aclTensor *softmaxMaxOut = executor->AllocTensor(DataType::DT_FLOAT, Format::FORMAT_ND, Format::FORMAT_ND);
    const aclTensor *softmaxSumOut = executor->AllocTensor(DataType::DT_FLOAT, Format::FORMAT_ND, Format::FORMAT_ND);

    // 调用inferShape
    auto ret = INFER_SHAPE(AiInfraSparseFlashAttentionPioneer,
                           OP_INPUT(query, key, value,
                                sparseIndices, blockTableOptional, actualSeqLengthsQueryOptional,
                                actualSeqLengthsKvOptional, queryRopeOptional, keyRopeOptional,
                                keySinkOptional, valueSinkOptional, metaDataOptional),
                           OP_OUTPUT(attentionOut, softmaxMaxOut, softmaxSumOut),
                           OP_ATTR(static_cast<float>(scaleValue), sparseBlockSize,
                                layoutQueryOptional, layoutKvOptional, sparseMode, preTokens,
                                nextTokens, attentionMode, returnSoftmaxLse, batchInvariant));
    if (ret != ACLNN_SUCCESS) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "AiInfraSparseFlashAttentionPioneer InferShape failed.");
        return {nullptr, nullptr};
    }

    // 发起aicore任务
    ADD_TO_LAUNCHER_LIST_AICORE(AiInfraSparseFlashAttentionPioneer,
                                OP_INPUT(query, key, value,
                                    sparseIndices, blockTableOptional, actualSeqLengthsQueryOptional,
                                    actualSeqLengthsKvOptional, queryRopeOptional, keyRopeOptional,
                                    keySinkOptional, valueSinkOptional, metaDataOptional),
                                OP_OUTPUT(attentionOut, softmaxMaxOut, softmaxSumOut),
                                OP_ATTR(static_cast<float>(scaleValue), sparseBlockSize,
                                    layoutQueryOptional, layoutKvOptional, sparseMode, preTokens,
                                    nextTokens, attentionMode, returnSoftmaxLse, batchInvariant));

    return {attentionOut, softmaxMaxOut, softmaxSumOut};
}

