void SFAMlaTiling::ZeroTensorProcess() const
{
    if (sfaInfo_->s2Size == 0) {
        /*
         * 1024，空tensor场景下，作为默认值完成后续计算
         * 避免matmal tiling  softmax tiling异常
         * kernel计算使用真实的seqSize=0, 与actuseq_len流程归一
         */
        sfaInfo_->s2Size = 1024;
    }
}

void SFAMlaTiling::InitParams()
{
    if (sfaInfo_->s2Size != 0 && sfaInfo_->sparseBlockSize <= 4) { // 4:当前支持范围
        perfMode_ = SFAPerfMode::V_TEMPLATE_MODE;
    } else {
        OP_LOGI(sfaInfo_->opName, "SFAPerfMode::C_TEMPLATE_MODE not supported anymore");
    }

    coreNum_ = aicNum_;

    uint32_t totalBN2S1 = 0;
    if (sfaInfo_->qLayout != SFALayout::TND) {
        totalBN2S1 = sfaInfo_->bSize * sfaInfo_->n2Size * sfaInfo_->s1Size;
    } else {
        totalBN2S1 = sfaInfo_->qTSize * sfaInfo_->n2Size;
    }

    if (sfaInfo_->batchInvariant) {
        splitKVFlag_ = false;
    } else {
        splitKVFlag_ = totalBN2S1 <= aicNum_ / HALF  ? true : false;
    }
    headDimAlign_ = Align(sfaInfo_->kHeadDim, BYTE_BLOCK); // 元素个数按照基本块大小对齐
    existMetaData_ = sfaInfo_->opParamInfo.metaData.tensor != nullptr ? true : false;
    ZeroTensorProcess();
    int32_t s1AvgSize = sfaInfo_->qLayout == SFALayout::TND
                        ? (sfaInfo_->s1Size + sfaInfo_->bSize - 1) / sfaInfo_->bSize : sfaInfo_->s1Size;
    setL2CacheHintDisableFlag_ = !splitKVFlag_ && s1AvgSize <= S1_AVERAGE_SIZE_LIMIT
                                    && sfaInfo_->bSize <= BATCH_SIZE_LIMIT;
}

void SFAMlaTiling::CalcUbBmm()
{
    uint32_t cubeMSize = sfaInfo_->gSize * sfaInfo_->s1Size;
    uint32_t maxMSize = mBaseSize_;
    if (cubeMSize > maxMSize) {
        cubeMSize = maxMSize;
    }

